        vm.assume(address(this).balance >= a);
        uint eb0 = address(c).balance;
        uint256 rec0;
        try c.balances(address(this)) returns (uint256 __r) { rec0 = __r; } catch { return; }
        bool rv;
        try c.withdraw() { rv = false; } catch { rv = true; }
        uint eb1 = address(c).balance;
        uint256 rec1;
        try c.balances(address(this)) returns (uint256 __r) { rec1 = __r; } catch { return; }
        assertTrue(!rv && rec1 == 0 && eb1 + rec0 == eb0 && address(this).balance >= a);
    }

    function testFuzz_run(uint256 a) public {
